create table if not EXISTS pessoa (
    id int NOT NULL AUTO_INCREMENT,
    nome text,
    email text,
    nascimento date,
    peso float,
    altura char(3),
    id_telegram int,
    bo_email boolean default false,
    ds_genero text,
    ts_validaemail timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY Key (id)
);

create table if not EXISTS pessoa_meta (
    id int NOT NULL AUTO_INCREMENT,
    id_pessoa int NOT NULL,
    nu_caloriasdiarias text,
    ts_criacao timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY Key (id),
    CONSTRAINT fk_pessoa_meta_pessoa FOREIGN KEY (id_pessoa) REFERENCES pessoa(id)
);

create table if not EXISTS user (
    id int NOT NULL AUTO_INCREMENT,
    id_pessoa int,
    password char(64),
    credential text DEFAULT null,
    bo_ativo boolean DEFAULT false,
    ts_criacao timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY Key (id),
    CONSTRAINT fk_user_pessoa FOREIGN KEY (id_pessoa) REFERENCES pessoa(id)
);

create table if not EXISTS alimento (
    id int NOT NULL AUTO_INCREMENT,
    ds_alimento text,
    tp_alimento text,
    nu_energia text,
    nu_proteina text,
    nu_carboidrato text,
    nu_fibra text,
    quantidade text,
    id_pessoa int,
    PRIMARY Key (id),
    CONSTRAINT fk_alimento_pessoa FOREIGN KEY (id_pessoa) REFERENCES pessoa(id)
);

