update alimento set quantidade = 100;

create table if not EXISTS refeicao (
    id int NOT NULL AUTO_INCREMENT,
    id_pessoa int not null,
    dt_refeicao date not null,
    PRIMARY Key (id),
    CONSTRAINT fk_refeicao_pessoa FOREIGN KEY (id_pessoa) REFERENCES pessoa(id)
);

create table if not EXISTS refeicao_tipo (
    id int NOT NULL AUTO_INCREMENT,
    tp_refeicao text not null,
    cor text,
    id_pessoa int not null,
    PRIMARY Key (id),
    CONSTRAINT fk_refeicao_tipo_pessoa FOREIGN KEY (id_pessoa) REFERENCES pessoa(id)
);

create table if not EXISTS refeicao_alimento (
    id int NOT NULL AUTO_INCREMENT,
    id_refeicao int not null,
    id_refeicao_tipo int not null,
    id_alimento int not null,
    nu_consumo int not null,
    ts_cadastro timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY Key (id),
    CONSTRAINT fk_refeicao_alimento_alimento FOREIGN KEY (id_alimento) REFERENCES alimento(id),
    CONSTRAINT fk_refeicao_alimento_refeicao FOREIGN KEY (id_refeicao) REFERENCES refeicao(id),
    CONSTRAINT fk_refeicao_alimento_refeicao_tipo FOREIGN KEY (id_refeicao_tipo) REFERENCES refeicao_tipo(id)
);

create table if not EXISTS requisicoes_bot (
    id int NOT NULL AUTO_INCREMENT,
    id_pessoa int not null,
    nu_linha_chat int not null,
    ds_requisicao text,
    id_refeicao_tipo int,
    id_alimento int,
    quantidade text,
    ts_cadastro timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY Key (id),
    CONSTRAINT fk_requisicoes_bot_pessoa FOREIGN KEY (id_pessoa) REFERENCES pessoa(id),
    CONSTRAINT fk_requisicoes_bot_refeicao_tipo FOREIGN KEY (id_refeicao_tipo) REFERENCES refeicao_tipo(id),
    CONSTRAINT fk_requisicoes_bot_alimento FOREIGN KEY (id_alimento) REFERENCES alimento(id)
);